import React, { useMemo, useState } from "react"
import { Link } from "gatsby"

import Shell from "../components/layout/Shell"
import Panel from "../components/layout/Panel"
import MarketChart from "../components/charts/MarketChart"
import BreakoutCard from "../components/dashboard/BreakoutCard"
import {
  DataTable,
  Delta,
  Icon,
  MetricCard,
  SegmentedControl,
  SignalBadge,
  Sparkline,
  TickerMark,
} from "../components/ui"

import {
  INDICES,
  CHART_RANGES,
  generateIndexSeries,
  getIndex,
  getMarketSentiment,
  getMarketBreadth,
  getWatchlist,
  getTrend,
  getSignalScore,
} from "../data/markets"
import { getBreakouts } from "../data/breakouts"
import { getIndicators } from "../data/indicators"
import { getCompany, ANCHOR_DATE } from "../data/companies"
import { getAllNews } from "../data/news"

/* -------------------------------------------------------------------------- */
/* Formatting                                                                  */
/* -------------------------------------------------------------------------- */

const DASH = "—"
const usd = (n, d = 2) => (n === null || !Number.isFinite(n) ? DASH : "$" + n.toFixed(d))

function compact(n) {
  if (n === null || !Number.isFinite(n)) return DASH
  const a = Math.abs(n)
  if (a >= 1e12) return (n / 1e12).toFixed(2) + "T"
  if (a >= 1e9) return (n / 1e9).toFixed(1) + "B"
  if (a >= 1e6) return (n / 1e6).toFixed(1) + "M"
  if (a >= 1e3) return (n / 1e3).toFixed(1) + "K"
  return String(Math.round(n))
}

const indexValue = index =>
  index.value.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })

/** Relative to the frozen anchor close, so "18 min ago" never drifts in a demo. */
const ANCHOR_CLOSE = (() => {
  const [y, m, d] = ANCHOR_DATE.split("-").map(Number)
  return Math.floor(Date.UTC(y, m - 1, d, 20, 0, 0) / 1000)
})()

function relativeTime(timestamp) {
  const seconds = ANCHOR_CLOSE - timestamp
  if (seconds < 60) return "just now"
  const minutes = Math.round(seconds / 60)
  if (minutes < 60) return minutes + "m ago"
  const hours = Math.round(minutes / 60)
  if (hours < 24) return hours + "h ago"
  return Math.round(hours / 24) + "d ago"
}

const CATEGORY_BY_SOURCE = {
  Reuters: "Markets",
  Bloomberg: "Markets",
  "PR Newswire": "Earnings",
  "Investor's Business Daily": "Technology",
  "Seeking Alpha": "Analysis",
  MarketWatch: "Macro",
  "Barron's": "Analysis",
  CNBC: "Markets",
}

/** The one identity treatment used in every table. Compact — ticker leads. */
/** "MARA Holdings, Inc. Common Stock" -> "MARA Holdings, Inc." */
function tidyName(name) {
  return String(name || "")
    .replace(/\s+(Common Stock|Class [A-Z] Common Stock|Ordinary Shares|Common Shares)$/i, "")
    .trim()
}

function Identity({ symbol, name }) {
  return (
    <div className="identity">
      <TickerMark symbol={symbol} size={24} />
      <div className="identity__text">
        <span className="identity__symbol">{symbol}</span>
        <span className="identity__name">{tidyName(name)}</span>
      </div>
    </div>
  )
}

/* -------------------------------------------------------------------------- */

export default function DashboardPage({ location }) {
  const [range, setRange] = useState("1M")
  const [indexKey, setIndexKey] = useState("SPX")

  const index = getIndex(indexKey)
  const series = useMemo(() => generateIndexSeries(indexKey, range), [indexKey, range])

  const sentiment = useMemo(() => getMarketSentiment(), [])
  const breadth = useMemo(() => getMarketBreadth(), [])
  const breakouts = useMemo(() => getBreakouts(), [])
  const news = useMemo(() => getAllNews().slice(0, 6), [])

  /*
   * One row model for every table on the page. Each row carries its own 1D trend
   * series, so the sparkline, the percentage and the colour all describe the
   * same window — the mismatch that made eight of fourteen rows contradict
   * themselves is impossible by construction now.
   */
  const rows = useMemo(
    () =>
      getWatchlist().map(row => {
        const ind = getIndicators(row.symbol, "1D")
        const company = getCompany(row.symbol)
        const trend = getTrend(row.symbol, "1D")
        const rating = getSignalScore(row.symbol, "1D")
        return {
          ...row,
          sector: company.sector,
          marketCap: company.marketCap,
          rsi: ind.latest.rsi14,
          volume: ind.candles.reduce((a, c) => a + c.volume, 0),
          momentum: ind.latest.macdHistogram,
          trend,
          rating,
        }
      }),
    []
  )

  const opportunities = useMemo(
    () =>
      rows
        .slice()
        .sort((a, b) => b.rating.score - a.rating.score || b.changePct - a.changePct)
        .slice(0, 6),
    [rows]
  )

  // One card per ticker — the full board lists a name once per signal type.
  const topBreakouts = useMemo(() => {
    const seen = new Set()
    const out = []
    for (const row of breakouts) {
      if (seen.has(row.symbol)) continue
      seen.add(row.symbol)
      out.push(row)
      if (out.length === 6) break
    }
    return out
  }, [breakouts])

  /* ---------------- Column definitions ---------------- */

  /*
   * The sparkline's window is whatever getTrend could actually source — 1D when
   * intraday data exists, 5D when it does not. The header reads that label off
   * the data rather than asserting "1D trend" over a five-day line, which is the
   * difference between a labelled comparison and a lie.
   */
  const trendLabel = rows.length && rows[0].trend ? rows[0].trend.label : "1D"

  const scannerColumns = [
    {
      key: "symbol",
      header: "Ticker",
      width: "210px",
      sortValue: r => r.symbol,
      render: r => <Identity symbol={r.symbol} name={r.name} />,
    },
    { key: "sector", header: "Sector", mobile: false, sortValue: r => r.sector, render: r => r.sector },
    {
      key: "price", header: "Price", numeric: true, align: "right",
      sortValue: r => r.price, render: r => usd(r.price),
    },
    {
      key: "changePct", header: "Change", align: "right",
      sortValue: r => r.changePct,
      render: r => <Delta value={r.changePct} percent digits={2} />,
    },
    {
      key: "trend", header: `${trendLabel} trend`, align: "right", sortable: false, mobile: false,
      render: r => <Sparkline trend={r.trend} width={72} height={22} />,
    },
    {
      key: "volume", mobile: false, header: "Volume", numeric: true, align: "right",
      sortValue: r => r.volume, render: r => compact(r.volume),
    },
    {
      key: "rsi", mobile: false, header: "RSI", numeric: true, align: "right",
      sortValue: r => r.rsi, render: r => (r.rsi === null ? DASH : r.rsi.toFixed(1)),
    },
    {
      key: "momentum", mobile: false, header: "Momentum", align: "right",
      sortValue: r => r.momentum,
      render: r => <Delta value={r.momentum} digits={3} showGlyph={false} />,
    },
    {
      key: "rating", header: "Signal", align: "right",
      sortValue: r => r.rating.score,
      render: r => (
        <SignalBadge
          signal={r.rating.label}
          score={r.rating.score}
          confidence={r.rating.confidence}
          reason={r.rating.reason}
        />
      ),
    },
  ]

  const watchlistColumns = [
    {
      key: "symbol", header: "Symbol", width: "210px",
      sortValue: r => r.symbol,
      render: r => <Identity symbol={r.symbol} name={r.name} />,
    },
    {
      key: "price", header: "Price", numeric: true, align: "right",
      sortValue: r => r.price, render: r => usd(r.price),
    },
    {
      key: "changeAbs", header: "Today", align: "right", mobile: false,
      sortValue: r => r.changeAbs,
      render: r => <Delta value={r.changeAbs} digits={2} showGlyph={false} />,
    },
    {
      key: "changePct", header: "Change", align: "right",
      sortValue: r => r.changePct,
      render: r => <Delta value={r.changePct} percent digits={2} />,
    },
    {
      key: "trend", header: `${trendLabel} trend`, align: "right", sortable: false,
      render: r => <Sparkline trend={r.trend} width={80} height={22} />,
    },
    {
      key: "marketCap", header: "Market cap", numeric: true, align: "right", mobile: false,
      sortValue: r => r.marketCap, render: r => compact(r.marketCap),
    },
    {
      key: "rating", header: "Signal", align: "right",
      sortValue: r => r.rating.score,
      render: r => (
        <SignalBadge
          signal={r.rating.label}
          score={r.rating.score}
          confidence={r.rating.confidence}
          reason={r.rating.reason}
        />
      ),
    },
  ]

  return (
    <Shell location={location}>
      <div className="page">
        {/* ---------- Title ---------- */}
        <header className="page__head">
          <div className="page__heading">
            <h1 className="page__title">Market overview</h1>
            <p className="page__lede">
              Track the market, discover opportunities, and stay ahead of momentum.
            </p>
          </div>
          <div className="page__actions">
            <Link className="btn btn--secondary" to="/scanner/">
              <Icon name="filter" size={15} className="btn__icon" />
              Open scanner
            </Link>
            <Link className="btn btn--primary" to="/watchlist/">
              <Icon name="plus" size={15} className="btn__icon" />
              Add to watchlist
            </Link>
          </div>
        </header>

        {/* ---------- Metrics ---------- */}
        <div className="kpi-grid">
          <MetricCard
            label="Market sentiment"
            icon="gauge"
            tone={sentiment.pct >= 60 ? "up" : sentiment.pct <= 40 ? "down" : "accent"}
            value={sentiment.pct}
            unit="%"
            meta={sentiment.label}
            bar={sentiment.pct}
            footnote={`${sentiment.bullish} of ${sentiment.total} technical checks bullish`}
          />
          <MetricCard
            label="Market breadth"
            icon="barChart"
            tone="up"
            value={breadth.pct}
            unit="%"
            meta="advancing"
            bar={breadth.pct}
            footnote={`${breadth.advancing} up · ${breadth.declining} down of ${breadth.total}`}
          />
          <MetricCard
            label="Breakouts"
            icon="zap"
            tone="accent"
            value={breakouts.length}
            meta="signals"
            footnote={`Across ${topBreakouts.length}+ tickers this session`}
          />
          <MetricCard
            label="Watchlist"
            icon="eye"
            tone="accent"
            value={rows.length}
            meta="tracked"
            footnote={`${rows.filter(r => r.changePct > 0).length} up on the session`}
          />
        </div>

        {/* ---------- Performance + opportunities ---------- */}
        <div className="dash-grid">
          <Panel flush>
            <div className="quote">
              <div>
                <p className="quote__label">
                  Market performance
                  {index.benchmark ? ` · ${index.benchmark} proxy` : ""}
                </p>
                <p className="quote__name">{index.name}</p>
                <p className="quote__figures">
                  <span className="quote__price">{indexValue(index)}</span>
                  <Delta value={index.changeAbs} digits={2} showGlyph={false} />
                  <Delta value={index.changePct} percent digits={2} />
                  <span className="quote__window">session</span>
                </p>
              </div>
              <div className="quote__controls">
                <SegmentedControl
                  options={INDICES.map(i => ({ label: i.name, value: i.key }))}
                  value={indexKey}
                  onChange={setIndexKey}
                  ariaLabel="Select index"
                />
                <SegmentedControl
                  options={CHART_RANGES}
                  value={range}
                  onChange={setRange}
                  ariaLabel="Select time range"
                />
              </div>
            </div>
            <MarketChart data={series} height={332} intraday={range === "1D"} type="area" />
          </Panel>

          <Panel
            title="Top opportunities"
            subtitle="Ranked by technical score"
            flush
            actions={
              <Link className="btn btn--ghost btn--sm" to="/scanner/">
                All
                <Icon name="arrowUpRight" size={13} className="btn__icon" />
              </Link>
            }
          >
            <div className="opps">
              {opportunities.map(row => (
                <div className="opps__row" key={row.symbol}>
                  <Identity symbol={row.symbol} name={row.name} />
                  <div className="opps__figures">
                    <Sparkline trend={row.trend} width={56} height={22} />
                    <div className="opps__numbers">
                      <span className="opps__price">{usd(row.price)}</span>
                      <Delta value={row.changePct} percent digits={2} className="delta--sm" />
                    </div>
                    <SignalBadge
                      signal={row.rating.label}
                      score={row.rating.score}
                      reason={row.rating.reason}
                    />
                  </div>
                </div>
              ))}
            </div>
          </Panel>
        </div>

        {/* ---------- Scanner ---------- */}
        <section className="section">
          <div className="section__head">
            <div className="section__heading">
              <h2 className="section__title">Market opportunities</h2>
              <p className="section__subtitle">
                Momentum, volume and technical strength across the tracked universe. Sort any column.
              </p>
            </div>
            <Link className="btn btn--secondary btn--sm" to="/scanner/">
              Open scanner
            </Link>
          </div>
          <Panel flush>
            <DataTable
              columns={scannerColumns}
              rows={rows}
              rowKey={r => r.symbol}
              initialSort={{ key: "changePct", direction: "desc" }}
              minWidth={1080}
            />
          </Panel>
        </section>

        {/* ---------- Breakouts ---------- */}
        <section className="section">
          <div className="section__head">
            <div className="section__heading">
              <h2 className="section__title">Today&rsquo;s breakouts</h2>
              <p className="section__subtitle">
                Names that cleared a level this session, with the crossing marked on each chart.
              </p>
            </div>
            <Link className="btn btn--secondary btn--sm" to="/breakouts/">
              All {breakouts.length} breakouts
            </Link>
          </div>
          <div className="breakout-grid">
            {topBreakouts.map(row => (
              <BreakoutCard row={row} key={row.id} />
            ))}
          </div>
        </section>

        {/* ---------- Watchlist ---------- */}
        <section className="section">
          <div className="section__head">
            <div className="section__heading">
              <h2 className="section__title">My watchlist</h2>
              <p className="section__subtitle">The names you track, and how they moved today.</p>
            </div>
            <Link className="btn btn--primary btn--sm" to="/watchlist/">
              <Icon name="plus" size={13} className="btn__icon" />
              Add stock
            </Link>
          </div>
          <Panel flush>
            <DataTable
              columns={watchlistColumns}
              rows={rows}
              rowKey={r => r.symbol}
              initialSort={{ key: "symbol", direction: "asc" }}
              minWidth={900}
            />
          </Panel>
        </section>

        {/* ---------- News ---------- */}
        <section className="section">
          <div className="section__head">
            <div className="section__heading">
              <h2 className="section__title">Market news</h2>
              <p className="section__subtitle">Headlines from the names you follow.</p>
            </div>
            <Link className="btn btn--secondary btn--sm" to="/news/">
              All news
            </Link>
          </div>
          <div className="news-grid">
            {news.map(item => (
              <article className="news" key={item.id}>
                <div className="news__top">
                  <TickerMark symbol={item.symbol} size={20} />
                  <span className="news__symbol">{item.symbol}</span>
                  <span className="badge badge--plain badge--sm">
                    {CATEGORY_BY_SOURCE[item.source] || "Markets"}
                  </span>
                  <span className="news__time">{relativeTime(item.timestamp)}</span>
                </div>
                <h3 className="news__headline">{item.headline}</h3>
                <p className="news__summary">{item.summary}</p>
                <p className="news__meta">{item.source}</p>
              </article>
            ))}
          </div>
        </section>
      </div>
    </Shell>
  )
}

export const Head = () => <title>Dashboard · MarketScan</title>
